import React, { useState } from "react";

export default function EventForm({addEvent}) {
    
    const [title, setTitle] = useState("");
    const [description, setDescription] = useState("");
    const [datetime, setDatetime] = useState("");

    const AddEventHandler = () => {
        //seteventsCollection(...eventsCollection, {id:1, titile:title, description:description, start:datetime})
    }

    return (
        <div className="left-div">
            <h2>Create Event</h2>
            <p>Event Name:</p>
            <input
                type="text"
                placeholder="Event Title"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                required
            />
            <br /><br /><br />
            <p>Event Description:</p>
            <textarea
                placeholder="Event Description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                required
            />
            <br /><br /><br />
            <p>Event Date:</p>
            <input
                type="datetime-local"
                value={datetime}
                onChange={(e) => setDatetime(e.target.value)}
                required
            />
            <br /><br /><br />
            <button className="buttonClass" onClick={AddEventHandler}>Add Event</button>
        </div>
    );
}
